app.post('/api/auth/register',asyncRoute(async(req,res)=>{const d=z.object({name:z.string().min(2).max(120),email:z.string().email().max(255),phone:z.string().max(24).optional(),password:z.string().min(10).max(100)}).parse(req.body);const hash=await hashPassword(d.password);const r=await query('INSERT INTO users(name,email,phone,password_hash) VALUES($1,lower($2),$3,$4) RETURNING id,name,email,phone,role',[d.name,d.email,d.phone||null,hash]);res.status(201).json({user:r.rows[0],token:sign(r.rows[0])})}));
app.post('/api/auth/login',asyncRoute(async(req,res)=>{const d=z.object({email:z.string().email(),password:z.string().min(1)}).parse(req.body);const r=await query('SELECT * FROM users WHERE email=lower($1) AND is_active=true',[d.email]);if(!r.rowCount||!await comparePassword(d.password,r.rows[0].password_hash))return res.status(401).json({error:'Invalid credentials'});const u=r.rows[0];res.json({user:{id:u.id,name:u.name,email:u.email,phone:u.phone,role:u.role},token:sign(u)})}));
