app.get('/api/products',asyncRoute(async(req,res)=>{const d=z.object({q:z.string().max(120).optional(),category:z.string().uuid().optional(),page:z.coerce.number().int().min(1).default(1),limit:z.coerce.number().int().min(1).max(60).default(24),sort:z.enum(['newest','price_asc','price_desc']).default('newest')}).parse(req.query);const params=[],where=["p.status='ACTIVE'"];if(d.q){params.push('%'+d.q+'%');where.push(`(p.name ILIKE $${params.length} OR p.description ILIKE $${params.length})`)}if(d.category){params.push(d.category);where.push(`p.category_id=$${params.length}`)}const sort={newest:'p.created_at DESC',price_asc:'p.price_pkr ASC',price_desc:'p.price_pkr DESC'}[d.sort];params.push(d.limit,(d.page-1)*d.limit);const r=await query(`SELECT p.id,p.name,p.slug,p.description,CASE WHEN EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id) THEN (SELECT min(v.price_pkr) FROM product_variants v WHERE v.product_id=p.id) ELSE p.price_pkr END price_pkr,p.compare_price_pkr,CASE WHEN EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id) THEN (SELECT COALESCE(sum(v.stock),0)::int FROM product_variants v WHERE v.product_id=p.id) ELSE p.stock END stock,EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id) has_variants,p.image_url,p.image_alt,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE ${where.join(' AND ')} ORDER BY ${sort} LIMIT $${params.length-1} OFFSET $${params.length}`,params);res.json(r.rows)}));
app.get('/api/products/:id',asyncRoute(async(req,res)=>{const r=await query("SELECT p.*,c.name category,CASE WHEN EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id) THEN (SELECT COALESCE(sum(v.stock),0)::int FROM product_variants v WHERE v.product_id=p.id) ELSE p.stock END available_stock,EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id) has_variants FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=$1 AND p.status='ACTIVE'",[req.params.id]);if(!r.rowCount)return res.status(404).json({error:'Product not found'});res.json(r.rows[0])}));
app.post('/api/seller/apply',auth,asyncRoute(async(req,res)=>{const d=z.object({storeName:z.string().min(2).max(180),address:z.string().max(500).optional()}).parse(req.body);if(req.user.role!=='CUSTOMER'&&req.user.role!=='SELLER')return res.status(403).json({error:'Not eligible'});await query('INSERT INTO seller_profiles(user_id,store_name,address) VALUES($1,$2,$3) ON CONFLICT(user_id) DO UPDATE SET store_name=excluded.store_name,address=excluded.address,status=\'PENDING\'',[req.user.sub,d.storeName,d.address||null]);res.status(201).json({status:'PENDING'})}));
