app.post('/api/orders',auth,asyncRoute(async(req,res)=>{const data=checkoutSchema.parse(req.body);const key=req.get('Idempotency-Key');if(key&&!/^[A-Za-z0-9._:-]{8,128}$/.test(key))return res.status(400).json({error:'Invalid Idempotency-Key header'});const result=await createOrder({data,userId:req.user.sub,email:req.user.email,idempotencyKey:key});res.status(201).json(result)}));
