app.patch('/api/admin/orders/:id/status',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{const d=z.object({status:z.enum(['PLACED','CONFIRMED','PROCESSING','READY_FOR_DISPATCH','SHIPPED','DELIVERED','CANCELLED','RETURNED'])}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const current=await c.query('SELECT * FROM orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!current.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Order not found'})}const previous=current.rows[0];const transitions={PENDING_PAYMENT:['CANCELLED'],PLACED:['CONFIRMED','PROCESSING','CANCELLED'],CONFIRMED:['PROCESSING','READY_FOR_DISPATCH','CANCELLED'],PROCESSING:['READY_FOR_DISPATCH','SHIPPED','CANCELLED'],READY_FOR_DISPATCH:['SHIPPED','CANCELLED'],SHIPPED:['DELIVERED','RETURNED'],DELIVERED:['RETURNED'],RETURNED:[],CANCELLED:[],REFUNDED:[]};if(d.status!==previous.status&&!(transitions[previous.status]||[]).includes(d.status)){throw Object.assign(new Error(`Order cannot move from ${previous.status} to ${d.status}.`),{status:409})}if(d.status==='CANCELLED'&&previous.status!=='CANCELLED'){const restored=await c.query("SELECT 1 FROM inventory_movements WHERE reason='Order cancelled' AND reference=$1 LIMIT 1",[previous.order_number]);if(!restored.rowCount){const items=await c.query('SELECT product_id,variant_id,quantity FROM order_items WHERE order_id=$1 AND product_id IS NOT NULL',[req.params.id]);for(const item of items.rows){if(item.variant_id)await c.query('UPDATE product_variants SET stock=stock+$1 WHERE id=$2',[item.quantity,item.variant_id]);else await c.query('UPDATE products SET stock=stock+$1,updated_at=now() WHERE id=$2',[item.quantity,item.product_id]);await c.query('INSERT INTO inventory_movements(product_id,variant_id,actor_id,quantity_change,reason,reference) VALUES($1,$2,$3,$4,$5,$6)',[item.product_id,item.variant_id,req.user.sub,item.quantity,'Order cancelled',previous.order_number])}}}const updated=await c.query('UPDATE orders SET status=$1,updated_at=now() WHERE id=$2 RETURNING *',[d.status,req.params.id]);await c.query('COMMIT');res.json(updated.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
