app.get('/api/seller/orders',auth,allow('SELLER','ADMIN'),asyncRoute(async(req,res)=>{const params=req.user.role==='ADMIN'?[]:[req.user.sub],filter=req.user.role==='ADMIN'?'true':'p.seller_id=$1';const r=await query(`SELECT o.id,o.order_number,o.status,o.created_at,o.recipient,o.city,o.province,COALESCE(sum(oi.line_total_pkr),0)::numeric seller_gross_pkr,json_agg(json_build_object('product',oi.product_name,'quantity',oi.quantity,'lineTotalPkr',oi.line_total_pkr)) items FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id WHERE ${filter} GROUP BY o.id ORDER BY o.created_at DESC LIMIT 300`,params);res.json(r.rows)}));
app.get('/api/seller/ledger',auth,allow('SELLER','ADMIN'),asyncRoute(async(req,res)=>{const params=req.user.role==='ADMIN'?[]:[req.user.sub],filter=req.user.role==='ADMIN'?'true':'seller_id=$1';res.json((await query(`SELECT * FROM seller_ledger WHERE ${filter} ORDER BY created_at DESC LIMIT 300`,params)).rows)}));
app.patch('/api/admin/products/:id',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{
  const d=z.object({name:z.string().min(2).max(220).optional(),slug:z.string().min(2).max(240).optional(),description:z.string().max(10000).optional(),pricePkr:z.number().nonnegative().optional(),comparePricePkr:z.number().nonnegative().nullable().optional(),stock:z.number().int().nonnegative().optional(),categoryId:z.string().uuid().nullable().optional(),imageUrl:z.string().url().nullable().optional(),status:z.enum(['DRAFT','ACTIVE','ARCHIVED']).optional(),sku:z.string().max(100).nullable().optional(),barcode:z.string().max(120).nullable().optional(),seoTitle:z.string().max(255).nullable().optional(),metaDescription:z.string().max(320).nullable().optional(),imageAlt:z.string().max(1000).nullable().optional()}).refine(x=>Object.keys(x).length>0).parse(req.body);
  const map={name:'name',slug:'slug',description:'description',pricePkr:'price_pkr',comparePricePkr:'compare_price_pkr',stock:'stock',categoryId:'category_id',imageUrl:'image_url',status:'status',sku:'sku',barcode:'barcode',seoTitle:'seo_title',metaDescription:'meta_description',imageAlt:'image_alt'};
  const sets=[],values=[];for(const [k,v] of Object.entries(d)){values.push(v);sets.push(`${map[k]}=$${values.length}`)}
  values.push(req.params.id);const r=await query(`UPDATE products SET ${sets.join(',')},updated_at=now() WHERE id=$${values.length} RETURNING *`,values);
  if(!r.rowCount)return res.status(404).json({error:'Product not found'});
  await query("INSERT INTO audit_logs(actor_id,action,entity,entity_id,metadata) VALUES($1,'PRODUCT_UPDATED','products',$2,$3::jsonb)",[req.user.sub,req.params.id,JSON.stringify({fields:Object.keys(d)})]);res.json(r.rows[0]);
}));
app.delete('/api/admin/products/:id',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{
  const r=await query("UPDATE products SET status='ARCHIVED',updated_at=now() WHERE id=$1 RETURNING id,status",[req.params.id]);
  if(!r.rowCount)return res.status(404).json({error:'Product not found'});
  await query("INSERT INTO audit_logs(actor_id,action,entity,entity_id) VALUES($1,'PRODUCT_ARCHIVED','products',$2)",[req.user.sub,req.params.id]);res.json(r.rows[0]);
}));
app.post('/api/admin/categories',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{
  const d=z.object({name:z.string().min(2).max(120),slug:z.string().min(2).max(140),description:z.string().max(2000).optional()}).parse(req.body);
  const r=await query('INSERT INTO categories(name,slug,description) VALUES($1,$2,$3) RETURNING *',[d.name,d.slug,d.description||null]);res.status(201).json(r.rows[0]);
}));
app.patch('/api/admin/categories/:id',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{
  const d=z.object({name:z.string().min(2).max(120).optional(),slug:z.string().min(2).max(140).optional(),description:z.string().max(2000).nullable().optional()}).refine(x=>Object.keys(x).length>0).parse(req.body);
  const m={name:'name',slug:'slug',description:'description'},sets=[],v=[];for(const [k,x] of Object.entries(d)){v.push(x);sets.push(`${m[k]}=$${v.length}`)}v.push(req.params.id);
  const r=await query(`UPDATE categories SET ${sets.join(',')} WHERE id=$${v.length} RETURNING *`,v);if(!r.rowCount)return res.status(404).json({error:'Category not found'});res.json(r.rows[0]);
}));
