app.get('/api/admin/reviews',auth,allow('ADMIN'),asyncRoute(async(req,res)=>res.json((await query('SELECT r.*,p.name product_name,u.name customer_name,u.email customer_email FROM product_reviews r JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC LIMIT 300')).rows)));
app.patch('/api/admin/reviews/:id',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{const d=z.object({approved:z.boolean()}).parse(req.body);const r=await query('UPDATE product_reviews SET approved=$1 WHERE id=$2 RETURNING *',[d.approved,req.params.id]);if(!r.rowCount)return res.status(404).json({error:'Review not found'});res.json(r.rows[0])}));
app.get('/api/admin/customers',auth,allow('ADMIN'),asyncRoute(async(req,res)=>res.json((await query("SELECT id,name,email,phone,role,is_active,created_at FROM users ORDER BY created_at DESC LIMIT 500")).rows)));
app.patch('/api/admin/customers/:id/status',auth,allow('ADMIN'),asyncRoute(async(req,res)=>{const d=z.object({isActive:z.boolean()}).parse(req.body);if(req.params.id===req.user.sub&&!d.isActive)return res.status(400).json({error:'You cannot deactivate your own admin account'});const r=await query('UPDATE users SET is_active=$1,updated_at=now() WHERE id=$2 AND role<>\'ADMIN\' RETURNING id,name,email,is_active',[d.isActive,req.params.id]);if(!r.rowCount)return res.status(404).json({error:'Customer not found or protected admin account'});res.json(r.rows[0])}));
app.get('/api/addresses',auth,asyncRoute(async(req,res)=>res.json((await query('SELECT * FROM addresses WHERE user_id=$1 ORDER BY is_default DESC,created_at DESC',[req.user.sub])).rows)));
app.post('/api/addresses',auth,asyncRoute(async(req,res)=>{const d=z.object({recipient:z.string().min(2).max(120),phone:z.string().min(8).max(24),addressLine:z.string().min(5).max(1000),city:z.string().min(2).max(100),province:z.string().min(2).max(100),postalCode:z.string().max(20).optional(),isDefault:z.boolean().default(false)}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');if(d.isDefault)await c.query('UPDATE addresses SET is_default=false WHERE user_id=$1',[req.user.sub]);const r=await c.query('INSERT INTO addresses(user_id,recipient,phone,address_line,city,province,postal_code,is_default) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[req.user.sub,d.recipient,d.phone,d.addressLine,d.city,d.province,d.postalCode||null,d.isDefault]);await c.query('COMMIT');res.status(201).json(r.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.delete('/api/addresses/:id',auth,asyncRoute(async(req,res)=>{const r=await query('DELETE FROM addresses WHERE id=$1 AND user_id=$2 RETURNING id',[req.params.id,req.user.sub]);if(!r.rowCount)return res.status(404).json({error:'Address not found'});res.json({ok:true})}));
app.post('/api/support/tickets/authenticated',auth,asyncRoute(async(req,res)=>{const d=z.object({subject:z.string().min(4).max(220),message:z.string().min(10).max(10000)}).parse(req.body);const r=await query('INSERT INTO support_tickets(user_id,email,subject,message) VALUES($1,$2,$3,$4) RETURNING id,status,created_at',[req.user.sub,req.user.email,d.subject,d.message]);res.status(201).json(r.rows[0])}));
app.get('/api/admin/audit-logs',auth,allow('ADMIN'),asyncRoute(async(req,res)=>res.json((await query('SELECT a.*,u.name actor_name,u.email actor_email FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT 500')).rows)));


app.patch('/api/me',auth,asyncRoute(async(req,res)=>{
  const d=z.object({name:z.string().min(2).max(120).optional(),phone:z.string().max(24).nullable().optional()}).refine(x=>Object.keys(x).length>0).parse(req.body);
  const r=await query('UPDATE users SET name=COALESCE($1,name),phone=CASE WHEN $2::boolean THEN $3 ELSE phone END,updated_at=now() WHERE id=$4 RETURNING id,name,email,phone,role',[d.name??null,Object.prototype.hasOwnProperty.call(d,'phone'),d.phone??null,req.user.sub]);res.json(r.rows[0]);
}));
app.post('/api/me/change-password',auth,asyncRoute(async(req,res)=>{
  const d=z.object({currentPassword:z.string().min(1).max(100),newPassword:z.string().min(12).max(100)}).parse(req.body);
  const r=await query('SELECT password_hash FROM users WHERE id=$1',[req.user.sub]);
  if(!r.rowCount||!await comparePassword(d.currentPassword,r.rows[0].password_hash))return res.status(400).json({error:'Current password is incorrect'});
  const hash=await hashPassword(d.newPassword);await query('UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2',[hash,req.user.sub]);res.json({ok:true,message:'Password changed. Sign in again on other devices.'});
}));
app.patch('/api/addresses/:id',auth,asyncRoute(async(req,res)=>{
  const d=z.object({recipient:z.string().min(2).max(120).optional(),phone:z.string().min(8).max(24).optional(),addressLine:z.string().min(5).max(1000).optional(),city:z.string().min(2).max(100).optional(),province:z.string().min(2).max(100).optional(),postalCode:z.string().max(20).nullable().optional(),isDefault:z.boolean().optional()}).refine(x=>Object.keys(x).length>0).parse(req.body);
  const c=await pool.connect();try{await c.query('BEGIN');if(d.isDefault)await c.query('UPDATE addresses SET is_default=false WHERE user_id=$1',[req.user.sub]);const map={recipient:'recipient',phone:'phone',addressLine:'address_line',city:'city',province:'province',postalCode:'postal_code',isDefault:'is_default'},sets=[],v=[];for(const [k,x] of Object.entries(d)){v.push(x);sets.push(`${map[k]}=$${v.length}`)}v.push(req.params.id,req.user.sub);const r=await c.query(`UPDATE addresses SET ${sets.join(',')} WHERE id=$${v.length-1} AND user_id=$${v.length} RETURNING *`,v);if(!r.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Address not found'})}await c.query('COMMIT');res.json(r.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}
}));

app.use((err,req,res,next)=>{
  if(err instanceof z.ZodError)return res.status(400).json({error:'Validation failed',details:err.issues});
  if(err instanceof SyntaxError && err.status===400 && 'body' in err)return res.status(400).json({error:'Invalid JSON body'});
  if(err.code==='23505')return res.status(409).json({error:'A record with these details already exists'});
  if(err.code==='23503')return res.status(400).json({error:'Referenced record does not exist'});
  if(err.code==='23514')return res.status(400).json({error:'Data violates a validation rule'});
  console.error(err);
  res.status(err.status||500).json({error:err.status&&err.status<500?err.message:'Internal server error',...(err.needsGatewaySetup?{needsGatewaySetup:true}:{})});
});
if (require.main === module) {
  const port = Number(process.env.PORT || 3000);
  if (!process.env.JWT_SECRET || process.env.JWT_SECRET.length < 32) {
    console.error('JWT_SECRET must be set and at least 32 characters');
    process.exit(1);
  }
  if (!process.env.DATABASE_URL) { console.error('DATABASE_URL must be configured'); process.exit(1); }
  if (process.env.NODE_ENV === 'production' && (!process.env.FRONTEND_ORIGIN || process.env.FRONTEND_ORIGIN.includes('localhost') || !process.env.PUBLIC_SITE_URL || process.env.PUBLIC_SITE_URL.includes('example'))) {
    console.error('Set FRONTEND_ORIGIN and PUBLIC_SITE_URL to the real storefront origin in production');
    process.exit(1);
  }
  app.listen(port, () => console.log(`Royal Marketplace API on ${port}`));
}

module.exports = app;
